 * @param {string} today
 * @returns {string}
 */
export function nextCharge(sub, today) {
  if (sub.cycle === CYCLE.WEEK) {
    let date = sub.since;
    while (date < today) {
      date = addDays(date, 7);
    }
    return date;
  }

  const step = sub.cycle === CYCLE.MONTH ? 1 : 12;
  let n = 0;
  let date = sub.since;
  while (date < today) {
    n += 1;
    date = addMonths(sub.since, n * step);
  }
  return date;
}

