1	import test from 'node:test';
2	import assert from 'node:assert/strict';
3	import { upcoming } from '../src/renewals.js';
4	
5	const plan = (name, cycle, since, price = 1000) => ({ name, price, cycle, since });
6	
7	test('lists the charges inside the window, a charge today included', () => {
8	  const subs = [plan('Today', 'monthly', '2026-09-24'), plan('In a week', 'monthly', '2026-08-31'), plan('Later', 'yearly', '2025-12-01')];
9	  const rows = upcoming(subs, '2026-10-24', 7);
10	  assert.deepEqual(rows.map((r) => [r.name, r.date, r.inDays]), [['Today', '2026-10-24', 0], ['In a week', '2026-10-31', 7]]);
11	});
12	
13	test('each row carries a short label for people', () => {
14	  const [row] = upcoming([plan('Netflix', 'monthly', '2026-09-27', 1299)], '2026-10-24', 7);
15	  assert.deepEqual(row, { name: 'Netflix', date: '2026-10-27', when: '27 Oct', inDays: 3, price: 1299, cycle: 'monthly' });
16	});
17	
18	test('lists upcoming charges soonest first, across a month boundary', () => {
19	  const subs = [plan('Gym', 'monthly', '2026-09-02'), plan('Music', 'monthly', '2026-09-30')];
20	  const rows = upcoming(subs, '2026-10-25', 14);
21	  assert.deepEqual(rows.map((r) => r.date), ['2026-10-30', '2026-11-02']);
22	});
23	
