import { addDays, addMonths } from './dates.js';

/** Billing cycles a plan can have. */
export const CYCLE = Object.freeze({ MONTH: 'monthly', WEEK: 'weekly', YEAR: 'yearly' });

/** Every supported cycle, as stored in the subscriptions file. */
export const CYCLES = Object.freeze(Object.values(CYCLE));

/**
 * What a plan costs per month, in whole cents (cut to the cent, except weekly which is rounded).
 * @param {{ price: number, cycle: string }} sub
 * @returns {number}
 */
export function monthlyCents(sub) {
  if (sub.cycle === CYCLE.MONTH) return Math.floor(sub.price);
  if (sub.cycle === CYCLE.WEEK) return Math.round(sub.price * 52 / 12);
  if (sub.cycle === CYCLE.YEAR) return Math.floor(sub.price / 12);
  return 0;
}

/**
 * The date of a plan's next charge on or after `today` ('YYYY-MM-DD').
 * Monthly/yearly charges fall on the day of the month of the first charge (`since`), or the last day of a shorter month.
 * Weekly charges occur every 7 days.
 * @param {{ cycle: string, since: string }} sub
 * @param {string} today
 * @returns {string}
 */
export function nextCharge(sub, today) {
  if (sub.cycle === CYCLE.WEEK) {
    let date = sub.since;
    while (date < today) {
      date = addDays(date, 7);
    }
    return date;
  }

  const step = sub.cycle === CYCLE.MONTH ? 1 : 12;
  let n = 0;
  let date = sub.since;
  while (date < today) {
    n += 1;
    date = addMonths(sub.since, n * step);
  }
  return date;
}

